47		metadata: {
48			description: "Fetch an object from an R2 bucket",
49			status: "stable",
50			owner: "Product: R2",
51		},
52		args: {
53			objectPath: {
54				describe: "The source object path in the form of {bucket}/{key}",
55				type: "string",
56				demandOption: true,
57			},
58			file: {
59				describe: "The destination file to create",
60				alias: "f",
61				conflicts: "pipe",
62				requiresArg: true,
63				type: "string",
64			},
65			pipe: {
66				describe:
67					"Enables the file to be piped to a destination, rather than specified with the --file option",
68				alias: "p",
69				conflicts: "file",
70				type: "boolean",
71			},
72			local: {
73				type: "boolean",
74				describe: "Interact with local storage",
75			},
76			remote: {
77				type: "boolean",
78				describe: "Interact with remote storage",
79				conflicts: "local",
80			},
81			"persist-to": {
82				type: "string",
83				describe: "Directory for local persistence",
84			},
85			jurisdiction: {
86				describe: "The jurisdiction where the object exists",
87				alias: "J",
88				requiresArg: true,
89				type: "string",
90			},
91		},
92		behaviour: {
93			printBanner({ pipe }) {
94				return !pipe;
95			},
96			printResourceLocation(args) {
97				return !args?.pipe;
98			},
99		},
100		positionalArgs: ["objectPath"],
101		async handler(objectGetYargs, { config }) {
102			const localMode = isLocal(objectGetYargs);
103			const { objectPath, pipe, jurisdiction } = objectGetYargs;
104			const { bucket, key } = validateAndReturnBucketAndKey(objectPath);
105			let fullBucketName = bucket;
106			if (jurisdiction !== undefined) {
107				fullBucketName += ` (${jurisdiction})`;
108			}
109	
110			let file = objectGetYargs.file;
111			if (!file && !pipe) {
112				file = key;
113			}
114			if (!pipe) {
115				logger.log(`Downloading "${key}" from "${fullBucketName}".`);
116			}
117	
118			let output: stream.Writable;
119			if (file) {
120				fs.mkdirSync(path.dirname(file), { recursive: true });
121				output = fs.createWriteStream(file);
122			} else {
123				output = process.stdout;
124			}
125			if (localMode) {
126				await usingLocalBucket(
127					objectGetYargs.persistTo,
128					config,
129					bucket,
130					async (r2Bucket) => {
131						const object = await r2Bucket.get(key);
132						if (object === null) {
133							throw new UserError("The specified key does not exist.");
134						}
135						// Note `object.body` is only valid inside this closure
136						await stream.promises.pipeline(object.body, output);
137					}
138				);
139			} else {
140				const accountId = await requireAuth(config);
141				const input = await getR2Object(
142					config,
143					accountId,
144					bucket,
145					key,
146					jurisdiction
147				);
148				if (input === null) {
149					throw new UserError("The specified key does not exist.");
150				}
151				await stream.promises.pipeline(input, output);
152			}
153			if (!pipe) {
154				logger.log("Download complete.");
155			}
156		},
157	});
