304	type ResponseWithBody = Response & { body: NonNullable<Response["body"]> };
305	export async function fetchR2Objects(
306		complianceConfig: ComplianceConfig,
307		resource: string,
308		bodyInit: RequestInit = {}
309	): Promise<ResponseWithBody | null> {
310		await requireLoggedIn(complianceConfig);
311		const auth = requireApiToken();
312		const headers = cloneHeaders(bodyInit.headers);
313		addAuthorizationHeader(headers, auth);
314		addUserAgent(headers);
315	
316		const response = await fetch(
317			`${getCloudflareApiBaseUrl(complianceConfig)}${resource}`,
318			{
319				...bodyInit,
320				headers,
321			}
322		);
323	
324		if (response.ok && response.body) {
325			return response as ResponseWithBody;
326		} else if (response.status === 404) {
327			return null;
328		} else {
329			throw new Error(
330				`Failed to fetch ${resource} - ${response.status}: ${response.statusText});`
331			);
332		}
333	}
