335	/**
336	 * This is a wrapper STOPGAP for getting the script which returns a raw text response.
337	 */
338	export async function fetchWorkerDefinitionFromDash(
339		complianceConfig: ComplianceConfig,
340		resource: string,
341		bodyInit: RequestInit = {}
342	): Promise<{ entrypoint: string; modules: File[] }> {
343		await requireLoggedIn(complianceConfig);
344		const auth = requireApiToken();
345		const headers = cloneHeaders(bodyInit.headers);
346		addAuthorizationHeader(headers, auth);
347		addUserAgent(headers);
348	
349		let response = await fetch(
350			`${getCloudflareApiBaseUrl(complianceConfig)}${resource}`,
351			{
352				...bodyInit,
353				headers,
354			}
355		);
356	
357		if (!response.ok || !response.body) {
358			logger.error(response.ok, response.body);
359			throw new Error(
360				`Failed to fetch ${resource} - ${response.status}: ${response.statusText});`
361			);
362		}
363	
364		const usesModules = response.headers
365			.get("content-type")
366			?.startsWith("multipart");
367	
368		if (usesModules) {
369			// For testing purposes only, sorry not sorry -- msw doesn't implement Response#formData
370			if (!response.formData) {
371				response = new Response(await response.text(), response);
372			}
373	
374			const form = await response.formData();
375			const files = Array.from(form.entries()).map(([filename, contents]) =>
376				contents instanceof File ? contents : new File([contents], filename)
377			);
378	
379			return {
380				entrypoint: response.headers.get("cf-entrypoint") ?? "src/index.js",
381				modules: files,
382			};
383		} else {
384			const contents = await response.text();
385			const file = new File([contents], "index.js", { type: "text" });
386	
387			return {
388				entrypoint: "index.js",
389				modules: [file],
390			};
391		}
392	}
