11	/**
12	 * Validates the file to be used for bulk put operations.
13	 *
14	 * The file is a list of {key, file} in JSON format.
15	 *
16	 * This functions throws a `UserError`:
17	 * - when the file does not exist
18	 * - when the file is not readable
19	 * - when the file is not a valid JSON
20	 * - when the file content is not an array of {key, file} objects
21	 * - when any of the `file` entries is not a file that exists
22	 * - when any of the `file` entries exceeds the maximum upload size
23	 *
24	 * @param filename The path to the bulk put JSON file
25	 * @returns
26	 */
27	export function validateBulkPutFile(
28		filename: string
29	): { key: string; file: string; size: number }[] {
30		if (!fs.existsSync(filename)) {
31			throw new UserError(`The file "${filename}" does not exist.`);
32		}
33	
34		let fileContent: string;
35		try {
36			fileContent = readFileSync(filename);
37		} catch {
38			throw new UserError(`The file "${filename}" is not readable.`);
39		}
40	
41		// The `size` property is added in the for loop below
42		let entries: { key: string; file: string; size: number }[];
43		try {
44			entries = JSON.parse(fileContent);
45		} catch {
46			throw new UserError(`The file "${filename}" is not a valid JSON.`);
47		}
48	
49		if (!Array.isArray(entries)) {
50			throw new UserError(
51				`The file "${filename}" must contain an array of entries.`
52			);
53		}
54	
55		for (const entry of entries) {
56			if (
57				entry === null ||
58				typeof entry !== "object" ||
59				!isRequiredProperty(entry, "key", "string") ||
60				!isRequiredProperty(entry, "file", "string")
61			) {
62				throw new UserError(
63					`Each entry in the file "${filename}" must be an object with "key" and "file" string properties.`
64				);
65			}
66	
67			if (!fs.existsSync(entry.file)) {
68				throw new UserError(`The file "${entry.file}" does not exist.`);
69			}
70	
71			const stat = fs.statSync(entry.file, { throwIfNoEntry: false });
72			if (!stat?.isFile()) {
73				throw new UserError(`The path "${entry.file}" is not a file.`);
74			}
75	
76			if (stat.size > MAX_UPLOAD_SIZE_BYTES) {
77				throw new UserError(
78					`The file "${entry.file}" exceeds the maximum upload size of ${prettyBytes(
79						MAX_UPLOAD_SIZE_BYTES,
80						{ binary: true }
81					)}.`
82				);
83			}
84	
85			entry.size = stat.size;
86		}
87	
88		return entries;
89	}
