100	 */
101	export function logBulkProgress(label: string, index: number, total: number) {
102		logger.log(
103			`${label} ${Math.floor(
104				(100 * index) / total
105			)}% (${formatNumber(index)} out of ${formatNumber(total)})`
106		);
107	}
