/**
 * HTTP header sent on R2 write requests to ask the API to reject the write with
 * a conflict if the target bucket has the data catalog enabled. This lets the
 * CLI warn the user before potentially leaving the catalog in an invalid state.
 */
export const R2_DATA_CATALOG_CHECK_HEADER = "cf-r2-data-catalog-check";

/**
 * API error code (returned alongside HTTP 409) indicating a write was rejected
 * because the bucket has the data catalog enabled.
 */
export const R2_DATA_CATALOG_CONFLICT_CODE = 10081;

/**
 * Prompt shown when a single write operation hits a data catalog conflict.
 */
export const R2_DATA_CATALOG_CONFLICT_PROMPT =
	"Data catalog is enabled for this bucket. Proceeding may leave the data catalog in an invalid state. Continue?";

/**
 * Upfront prompt shown before a bulk upload that may overwrite existing objects.
 */
export const R2_BULK_PUT_DATA_CATALOG_PROMPT =
	"Bulk upload may overwrite existing objects. If this bucket has data catalog enabled, this operation could leave the catalog in an invalid state. Continue?";

/**
 * Returns whether the given error is an R2 data catalog conflict, i.e. an
 * HTTP 409 response carrying error code 10081.
 */
export function isR2DataCatalogConflict(error: unknown): boolean {
	return error instanceof APIError && error.code === R2_DATA_CATALOG_CONFLICT_CODE;
}
